      final store = ModelCapsStore();
      const model = _model;
      store.learnFromRefusal(model, const MessageCapRefusal());
      store.takePremptivePass('fake', 'm');
      store.learnFromRefusal(model, const MessageCapRefusal());
      expect(store.takePremptivePass('fake', 'm'), isTrue);
    });

