  RegExp(
    r'\barray length\b(?:\s+\d[\d,]*)?\s+exceeds\s+limit\b',
    caseSensitive: false,
  ),
  RegExp(r'\btoo many messages\b', caseSensitive: false),
  RegExp(r'\bmessages count exceeds\b', caseSensitive: false),
];

