const _model = Model(
  id: 'cap-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: 1000000,
  maxTokens: 4096,
);

List<AssistantMessageEvent> _capRefusalTurn(String error) {
  final msg = testAssistant(
    stopReason: StopReason.error,
    errorMessage: error,
  );
