    StartEvent(partial: msg),
    ErrorEvent(reason: StopReason.error, error: msg),
  ];
}

AgentCli _bootCli({
  required MemoryExecutionEnv env,
  required FakeCliIO io,
  required String homeDir,
  required StreamFunction stream,
}) => AgentCli(
  config: AgentCliConfig(
