        // of hideable turns for the relief pass), then the provider's cap
        // refusal, the relief's summarizer, and the retried request.
        final turns = <List<AssistantMessageEvent>>[
          for (var i = 1; i <= 8; i++)
            toolTurn([
              ToolCall(
                id: 't$i',
                name: 'read',
                arguments: {'path': 'note.txt'},
