/// must respect the same budget the boot cap gates on: when the live
/// request sits over the compaction trigger (window − reserve), the
/// remainder is compacted HERE — mid-run, inside the auto-closing tool
/// call — and the loop adopts the capped transcript at the next turn
/// boundary ([CheckpointRewindController.requestContextResync]), so no
/// request ever rides the uncapped restore. Degradation (AC5) rides the
/// same pipeline as everywhere else: summarizer failure → local-trim
/// valve → `[context trimmed]`; an unexpected throw still boots/keeps
/// the run alive with a visible dim note (the pre-flight re-fires before
/// the next turn either way).
Future<void> _guardCheckpointRestoreBudget(
  CheckpointAutoCloseReason reason,
  CheckpointState checkpoint,
) async {
  // Only the user-turn close restores an unpruned detour; an anchorGone
  // close means the transcript was ALREADY rebuilt (reload/compaction).
  if (reason != CheckpointAutoCloseReason.userTurn) return;
  if (_session == null) return;
  if (_agent.state.messages.isEmpty) return;
  if (_runAbortRequested) return;
  final tokens = _liveRequestTokens();
  if (!shouldCompact(
    tokens,
    _effectiveContextWindow,
    _effectiveCompactionSettings,
  )) {
    return;
  }
  _pushBusyPhase('Compacting context…');
  _logDiagnostic(
    'checkpoint restore budget guard start sid=$_logSid tokens=$tokens',
  );
  try {
    await _runAutoCompact('[auto-compacted]');
    // The compaction replaced state.messages MID-RUN: arm the resync so
    // the next turn boundary swaps the loop's stale context for the
    // capped one — the remainder rides no over-budget request.
    _checkpoints.requestContextResync();
    // Honest receipt: name the outcome, not the intent — a pass that
    // stayed over the trigger (huge keep region, degenerate overhead)
    // must not read as capped.
    final after = _liveRequestTokens();
    io.writeln(
      _style.dim(
        shouldCompact(
              after,
              _effectiveContextWindow,
              _effectiveCompactionSettings,
            )
            ? '[checkpoint] detour closed over the compaction trigger '
                  '($tokens tokens) — compaction ran but the context stayed '
                  'over the trigger ($after); it retries before the next turn'
            : '[checkpoint] detour closed over the compaction trigger '
                  '($tokens tokens) — context auto-compacted before the '
                  'next request',
      ),

        smolModel: smol?.model,
        mainStream: _streamFunction,
        mainModel: _agent.state.model,
      ),
      hooks: hooks,
      prompts: CompactionPrompts.fromOverrides(config.promptOverrides),
      // Issue #287: structured is the default fallback; an explicit
      // config choice (config.compactionEngine) or a live override from
      // the settings flow (config.liveCompactionEngine, #288) still wins.
      engine:
          config.liveCompactionEngine ??
          config.compactionEngine ??
          CompactionEngine.structured,
      // Judge budget knob (issue #541): null keeps the 300s default
      // (gh-740 M1: raised from 90s — a 262k-token checkpoint on a slow
      // provider could not be summarized within 90s, bricking sessions).
      attemptBudget: Duration(
        seconds: config.compactionJudgeBudgetSeconds ?? 300,
      ),
      // gh-1409: the enabled skills' operative lines ride every
      // summarization prompt as the verbatim-preserve pinned block.
      operativeSkills: _enabledSkills,
      // Issue #1085 M1/M3: linked cancellation — see [_runAutoCompact].
      runToken: token,
      // gh-1680 AC4: the learned per-model message cap rides every
      // compaction — `count ≥ cap − margin` fires even when the token
      // trigger is untouched (the pre-emptive trigger).
      messageCap: _modelCaps.learnedCapFor(_agent.state.model),
      memoryExtractionHook: (text) async {
        final tui = _tuiController;
        tui?.setBusyPhase('Extracting memory…');
        // Best-effort and BOUNDED: a wedged smol endpoint used to keep the
        // phase label up for the whole role-chain retry ladder (minutes
        // per pass — the "Extracting memory… 1025s" stall). Cancel the
        // extraction stream after the deadline, hard-cap the wait anyway,
        // and restore the compaction phase label either way. A timeout
        // skips extraction for this pass only — never the compaction.
        final source = CancelTokenSource();
        final deadline = Timer(
          AgentCli._memoryExtractionDeadline,
          source.cancel,
        );
        try {
          final hook = compactionMemoryHook(
            memory: _memory,
            stream: smol?.stream ?? _streamFunction,
            model: smol?.model ?? _agent.state.model,
            cancelToken: source.token,
          );
          if (hook != null) {
            await hook(text).timeout(AgentCli._memoryExtractionHardCap);
          }
        } on TimeoutException {
          _logDiagnostic(
            'memory extraction skipped: exceeded '
            '${AgentCli._memoryExtractionHardCap.inSeconds}s hard cap',
          );
        } finally {
          deadline.cancel();
          _pushBusyPhase('Compacting context…');
        }
      },
      force: label == '[compacted]',
    ).run();
    _persistedCount = _agent.state.messages.length;
    return hooks.reportedPass;
  }
}

