    // The trim genuinely dropped the old kept messages.
    final texts = [
      for (final m in turnContext.messages)
        if (m is UserMessage) messageText(m),
    ];
    expect(texts.where((t) => t.startsWith('kept1 ')), isEmpty);
  },
);

