  // The wake gate (see [_sessionLoadsInFlight]) — same contract as
  // [_loadSession]: creation resets agent state too.
  _sessionLoadsInFlight++;
  try {
    return await _createSessionInner(name: name);
  } finally {
    _sessionLoadsInFlight--;
  }
}

