import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

const _window = 32768;
const _reserve = 8192;
// CompactionSettings.forWindow(32768): reserve = min(16384, window ~/ 4).
final _threshold = _window - _reserve;

Model get _model => const Model(
  id: 'test-model',
